def seed_roles_and_assign(apps, schema_editor):
    """Give every MSP/STP organization its preset roles, and move existing
    MSP_USER / STP_USER staff onto the default preset so nobody loses access."""
    from apps.core.access import DEFAULT_PRESET, seed_roles
    Organization = apps.get_model('tenants', 'Organization')
    OrgRole = apps.get_model('users', 'OrgRole')
    User = apps.get_model('users', 'User')
    for org in Organization.objects.filter(tenant_type__in=['MSP', 'STP']):
        seed_roles(org, role_model=OrgRole)
        default = OrgRole.objects.filter(organization=org, name=DEFAULT_PRESET[org.tenant_type]).first()
        if default:
            User.objects.filter(organization=org, role__in=['MSP_USER', 'STP_USER'], access_role__isnull=True).update(access_role=default)


